const elInfo = await browserjs(787784006, () => {
  // Check shadow DOM or custom elements
  function getAllElements(root = document.body) {
    const res = [];
    const walker = document.createTreeWalker(root, NodeFilter.SHOW_ELEMENT);
    while (walker.nextNode()) {
      const el = walker.currentNode;
      res.push(el);
      if (el.shadowRoot) {
        res.push(...getAllElements(el.shadowRoot));
      }
    }
    return res;
  }
  const all = getAllElements();
  const links = all.filter(el => el.tagName === 'A' || el.getAttribute('href') || el.innerText?.includes('Find Care') || el.innerText?.includes('Individual & Family'));
  return links.map(el => ({
    tag: el.tagName,
    href: el.getAttribute('href') || el.href,
    text: el.innerText?.trim()?.slice(0, 50)
  })).slice(0, 20);
});

