  { name: "Martha A. Snyder, MD", url: "https://www.dukehealth.org/find-doctors-physicians/martha-snyder-md" },
  { name: "Larissa Saldana, MD", url: "https://www.dukehealth.org/find-doctors-physicians/larissa-saldana-md" },
  { name: "Kunjan Shakya, MD, FAAP", url: "https://www.dukehealth.org/find-doctors-physicians/kunjan-shakya-md-faap" },
  { name: "Amber Whitmill, MD", url: "https://www.dukehealth.org/find-doctors-physicians/amber-whitmill-md" },
  { name: "Elizabeth Briere, MD", url: "https://www.dukehealth.org/find-doctors-physicians/elizabeth-briere-md" }
];

const results = [];
for (const doc of dukeDocs) {
  await tool.navigate({ tabId: 787783793, url: doc.url });
  await tool.wait_for({ tabId: 787783793, condition: "load_state", value: "domcontentloaded", timeout_ms: 10000 });
  const data = await browserjs(787783793, () => {
    const text = document.body.innerText;
