      hasBCBS: text.includes('Blue Cross'),
      hasUHC: text.includes('United Healthcare') || text.includes('UnitedHealthcare')
    };
  });
  results.push({ ...doc, ...data });
}

console.log("Duke Doctors Verification:\n", JSON.stringify(results, null, 2));

