const pedTabs = [
  { tabId: 787784012, name: "Theresa Flynn, MD, MPH" },
  { tabId: 787784013, name: "Lori Stiegemeier, DO" },
  { tabId: 787784014, name: "Ashley Wallace, MD" },
  { tabId: 787784015, name: "Brian H. Eichner, MD" },
  { tabId: 787784016, name: "Martha A. Snyder, MD" },
  { tabId: 787784017, name: "Larissa Saldana, MD" },
  { tabId: 787784018, name: "Kunjan Shakya, MD, FAAP" },
  { tabId: 787784019, name: "Elizabeth Briere, MD" },
  { tabId: 787784020, name: "Miranda Dey, MD" },
  { tabId: 787784021, name: "Elizabeth Cleland-Roberts, MD, FAAP" },
  { tabId: 787784022, name: "Carrie Dow-Smith, MD" }
];

const verifiedPediatricians = [];

for (const p of pedTabs) {
  await tool.wait_for({ tabId: p.tabId, condition: "load_state", value: "domcontentloaded", timeout_ms: 10000 });
  const data = await browserjs(p.tabId, () => {
    const text = document.body.innerText;
    const h1 = document.querySelector('h1')?.innerText?.trim();
    const address = document.querySelector('.address, address, [class*="address"]')?.innerText?.replace(/\s+/g, ' ');
    const locIdx = text.indexOf('Locations');
    const locSnippet = locIdx !== -1 ? text.slice(locIdx, locIdx + 300).replace(/\s+/g, ' ') : null;

    return {
      title: document.title,
      url: window.location.href,
      h1,
      address: address || locSnippet,
      hasAetna: text.includes('Aetna'),
      hasBCBS: text.includes('Blue Cross') || text.includes('BCBS'),
      hasUHC: text.includes('United') || text.includes('UHC')
    };
  });
  verifiedPediatricians.push({ ...p, ...data });
}

console.log("Verified Pediatricians Summary:\n", JSON.stringify(verifiedPediatricians, null, 2));

