const daycareQueries = [
  "Children's Lighthouse of Raleigh official site",
  "Cornerstone Learning Center Raleigh NC official site",
  "The Goddard School of Raleigh Midtown official site",
  "Primrose School of Midtown Raleigh official site",
  "Primary Beginnings Child Development Center Raleigh official site",
  "Spanish for Fun Duraleigh Raleigh NC official site",
  "Highwoods Parks KinderCare Raleigh NC official site",
  "Copperfield Road KinderCare Raleigh NC official site",
  "Bright Horizons at Raleigh NC official site",
  "Little by Little Preschool Raleigh NC official site"
];

const foundDaycares = [];

for (const q of daycareQueries) {
  const url = `https://www.google.com/search?q=${encodeURIComponent(q)}`;
  await tool.navigate({ tabId: 787783793, url });
  await tool.wait_for({ tabId: 787783793, condition: "selector_visible", value: "h3", timeout_ms: 5000 });
  const firstResult = await browserjs(787783793, () => {
    const h3s = Array.from(document.querySelectorAll('h3'));
    for (const h of h3s) {
      const a = h.closest('a');
      if (a && a.href) {
        return {
          title: h.innerText,
          href: a.href,
          snippet: a.closest('div')?.innerText?.replace(/\n+/g, ' ')?.slice(0, 200)
        };
      }
    }
    return null;
  });
  foundDaycares.push({ query: q, result: firstResult });
}

console.log("Daycare search results:\n", JSON.stringify(foundDaycares, null, 2));

