  { tabId: 787784032, name: "Chesterbrook Academy Preschool Raleigh" }
];

const daycareDetails = [];

for (const d of daycareTabs) {
  try {
    await tool.wait_for({ tabId: d.tabId, condition: "load_state", value: "domcontentloaded", timeout_ms: 10000 });
    const data = await browserjs(d.tabId, () => {
      const text = document.body.innerText;
      const h1 = document.querySelector('h1')?.innerText?.trim();
      return {
        url: window.location.href,
        title: document.title,
        h1,
        snippet: text.slice(0, 1500).replace(/\s+/g, ' ')
      };
    });
    daycareDetails.push({ ...d, ...data });
  } catch (e) {
    daycareDetails.push({ ...d, error: e.message });
  }
}

